<?php
declare(strict_types=1);

function expense_resolve_job_card(string $reference): array
{
    $reference = trim($reference);
    if ($reference === '' || $reference === '0') return ['id' => 0, 'reference' => ''];
    $numeric = ctype_digit($reference);
    $statement = database()->prepare('SELECT id, job_card_no FROM job_cards WHERE ' . ($numeric ? 'id = :reference' : 'job_card_no = :reference') . ' LIMIT 1');
    $statement->execute(['reference' => $numeric ? $reference : strtoupper($reference)]);
    $jobCard = $statement->fetch();
    return ['id' => (int) ($jobCard['id'] ?? 0), 'reference' => $jobCard['job_card_no'] ?? $reference];
}

function ensure_expense_tables(): void
{
    static $ready=false; if($ready)return; ensure_suppliers_table(); $pdo=database();
    $pdo->exec("CREATE TABLE IF NOT EXISTS expenses (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT, expense_no VARCHAR(30) NOT NULL, expense_date DATE NOT NULL, category VARCHAR(100) NOT NULL, reference_no VARCHAR(100) NULL, description VARCHAR(255) NOT NULL, supplier_id BIGINT UNSIGNED NULL, payment_terms ENUM('cash','credit','partial') NOT NULL DEFAULT 'cash', payment_method ENUM('cash','card','bank','cheque','other') NOT NULL DEFAULT 'cash', location VARCHAR(100) NULL, bill_file VARCHAR(255) NULL, subtotal DECIMAL(12,2) NOT NULL DEFAULT 0, discount DECIMAL(12,2) NOT NULL DEFAULT 0, tax_rate DECIMAL(5,2) NOT NULL DEFAULT 0, tax_amount DECIMAL(12,2) NOT NULL DEFAULT 0, total_amount DECIMAL(12,2) NOT NULL DEFAULT 0, paid_amount DECIMAL(12,2) NOT NULL DEFAULT 0, balance_amount DECIMAL(12,2) NOT NULL DEFAULT 0, payment_date DATE NULL, payment_note TEXT NULL, notes TEXT NULL, status ENUM('draft','pending','paid','partial','due','cancelled') NOT NULL DEFAULT 'pending', created_by BIGINT UNSIGNED NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, PRIMARY KEY(id), UNIQUE KEY expenses_no_unique(expense_no), KEY expenses_date_index(expense_date), KEY expenses_category_index(category), KEY expenses_status_index(status), CONSTRAINT expenses_supplier_fk FOREIGN KEY(supplier_id) REFERENCES suppliers(id) ON DELETE SET NULL, CONSTRAINT expenses_user_fk FOREIGN KEY(created_by) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");
    $pdo->exec("CREATE TABLE IF NOT EXISTS expense_items (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT, expense_id BIGINT UNSIGNED NOT NULL, item_name VARCHAR(190) NOT NULL, quantity DECIMAL(12,2) NOT NULL DEFAULT 1, unit_price DECIMAL(12,2) NOT NULL DEFAULT 0, amount DECIMAL(12,2) NOT NULL DEFAULT 0, PRIMARY KEY(id), KEY expense_items_expense_index(expense_id), CONSTRAINT expense_items_expense_fk FOREIGN KEY(expense_id) REFERENCES expenses(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");
    $pdo->exec("CREATE TABLE IF NOT EXISTS expense_categories (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT, category_code VARCHAR(30) NOT NULL, category_name VARCHAR(120) NOT NULL, description TEXT NULL, status ENUM('active','inactive') NOT NULL DEFAULT 'active', created_by BIGINT UNSIGNED NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, PRIMARY KEY(id), UNIQUE KEY expense_categories_code_unique(category_code), UNIQUE KEY expense_categories_name_unique(category_name)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");
    $pdo->exec("CREATE TABLE IF NOT EXISTS expense_external_parts (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT, expense_id BIGINT UNSIGNED NOT NULL, job_card_id BIGINT UNSIGNED NULL, vehicle_id BIGINT UNSIGNED NULL, part_name VARCHAR(190) NOT NULL, part_code VARCHAR(80) NULL, quantity DECIMAL(12,2) NOT NULL DEFAULT 1, unit_cost DECIMAL(12,2) NOT NULL DEFAULT 0, total_cost DECIMAL(12,2) NOT NULL DEFAULT 0, supplier_id BIGINT UNSIGNED NULL, vendor_name VARCHAR(160) NULL, invoice_no VARCHAR(100) NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(id), KEY expense_external_parts_expense_index(expense_id), CONSTRAINT expense_external_parts_expense_fk FOREIGN KEY(expense_id) REFERENCES expenses(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");
    foreach (["ALTER TABLE expenses ADD COLUMN expense_type ENUM('general','external_part') NOT NULL DEFAULT 'general' AFTER category", "ALTER TABLE expenses ADD COLUMN vendor_supplier_name VARCHAR(160) NULL AFTER supplier_id", "ALTER TABLE expenses ADD COLUMN job_card_id BIGINT UNSIGNED NULL AFTER vendor_supplier_name", "ALTER TABLE expenses ADD COLUMN vehicle_id BIGINT UNSIGNED NULL AFTER job_card_id", "ALTER TABLE expenses ADD COLUMN attachment_path VARCHAR(255) NULL AFTER bill_file"] as $sql) { try { $pdo->exec($sql); } catch (Throwable $ignored) {} }
    $pdo->exec("INSERT IGNORE INTO expense_categories (category_code,category_name) VALUES ('EXP-CAT-001','Electricity Bill'),('EXP-CAT-002','Water Bill'),('EXP-CAT-003','Rent'),('EXP-CAT-004','Internet / Telephone'),('EXP-CAT-005','Fuel / Transport'),('EXP-CAT-006','Office Expenses'),('EXP-CAT-007','Repairs & Maintenance'),('EXP-CAT-008','External Spare Part Purchase'),('EXP-CAT-009','Other')"); $ready=true;
}
function expense_categories(bool $activeOnly=true): array { $rows=database()->query('SELECT category_name FROM expense_categories'.($activeOnly?" WHERE status='active'":'').' ORDER BY category_name')->fetchAll(PDO::FETCH_COLUMN); return $rows; }
function expense_category_rows(): array { return database()->query("SELECT c.*,COUNT(e.id) expense_count FROM expense_categories c LEFT JOIN expenses e ON e.category=c.category_name AND e.status<>'cancelled' GROUP BY c.id ORDER BY c.category_name")->fetchAll(); }
function expense_suppliers(): array { return database()->query("SELECT id,name,supplier_code FROM suppliers WHERE status='active' ORDER BY name")->fetchAll(); }
function expense_input(?array $source=null): array { $source??=$_POST;$items=[];foreach((array)($source['items']??[]) as $item){$name=trim((string)($item['name']??''));if($name!==''||(float)($item['quantity']??0)>0)$items[]=['name'=>$name,'quantity'=>(string)($item['quantity']??'1'),'unit_price'=>(string)($item['unit_price']??'0')];}return ['expense_date'=>trim((string)($source['expense_date']??date('Y-m-d'))),'category'=>trim((string)($source['category']??'')),'reference_no'=>trim((string)($source['reference_no']??'')),'description'=>trim((string)($source['description']??'')),'supplier_id'=>max(0,(int)($source['supplier_id']??0)),'payment_terms'=>in_array($source['payment_terms']??'', ['cash','credit','partial'],true)?$source['payment_terms']:'cash','payment_method'=>in_array($source['payment_method']??'', ['cash','card','bank','other'],true)?$source['payment_method']:'cash','location'=>trim((string)($source['location']??'')),'discount'=>(string)($source['discount']??'0'),'tax_rate'=>(string)($source['tax_rate']??'18'),'paid_amount'=>(string)($source['paid_amount']??'0'),'payment_date'=>trim((string)($source['payment_date']??date('Y-m-d'))),'payment_note'=>trim((string)($source['payment_note']??'')),'notes'=>trim((string)($source['notes']??'')),'status'=>in_array($source['status']??'', ['draft','pending','paid','partial','due'],true)?$source['status']:'pending','items'=>$items]; }
function expense_input_extended(?array $source=null): array { $input=expense_input($source);$source??=$_POST;$input['expense_type']=($source['expense_type']??'')==='external_part'?'external_part':'general';if($input['expense_type']==='external_part'){$input['category']='External Spare Part Purchase';$input['description']=trim((string)($source['external_part_name']??''));}$input['supplier_id']=max(0,(int)($source['supplier_id_external']??$source['supplier_id']??0));$input['vendor_supplier_name']=trim((string)($source['vendor_supplier_name']??''));$jobCard=expense_resolve_job_card((string)($source['job_card_id']??''));$input['job_card_id']=$jobCard['id'];$input['job_card_reference']=$jobCard['reference'];$input['vehicle_id']=max(0,(int)($source['vehicle_id']??0));$input['external_part_name']=trim((string)($source['external_part_name']??''));$input['external_part_code']=trim((string)($source['external_part_code']??''));$input['external_quantity']=(string)($source['external_quantity']??'1');$input['external_unit_cost']=(string)($source['external_unit_cost']??'0');$input['external_invoice_no']=trim((string)($source['external_invoice_no']??''));$input['purchase_date']=trim((string)($source['purchase_date']??$input['expense_date']));$input['external_parts']=[];foreach((array)($source['external_parts']??[]) as $part){$name=trim((string)($part['name']??''));if($name!==''||(float)($part['quantity']??0)>0)$input['external_parts'][]=['name'=>$name,'code'=>trim((string)($part['code']??'')),'quantity'=>(string)($part['quantity']??'1'),'buying_price'=>(string)($part['buying_price']??'0'),'selling_price'=>(string)($part['selling_price']??'0')];}if(!$input['external_parts']&&$input['external_part_name']!=='')$input['external_parts']=[['name'=>$input['external_part_name'],'code'=>$input['external_part_code'],'quantity'=>$input['external_quantity'],'buying_price'=>$input['external_unit_cost'],'selling_price'=>'0']];return $input; }
function expense_rows(array $filters=[]): array { $w=[];$p=[];if(($filters['search']??'')!==''){$w[]='(e.expense_no LIKE :q OR e.description LIKE :q OR e.category LIKE :q OR s.name LIKE :q)';$p['q']='%'.$filters['search'].'%';}if(($filters['status']??'')!==''){$w[]='e.status=:status';$p['status']=$filters['status'];}if(($filters['from']??'')!==''){$w[]='e.expense_date>=:from_date';$p['from_date']=$filters['from'];}if(($filters['to']??'')!==''){$w[]='e.expense_date<=:to_date';$p['to_date']=$filters['to'];}if((int)($filters['created_by']??0)>0){$w[]='e.created_by=:created_by';$p['created_by']=(int)$filters['created_by'];}$sql='SELECT e.*,s.name supplier_name,u.name AS created_by_name FROM expenses e LEFT JOIN suppliers s ON s.id=e.supplier_id LEFT JOIN users u ON u.id=e.created_by'.($w?' WHERE '.implode(' AND ',$w):'').' ORDER BY e.expense_date DESC,e.id DESC';$s=database()->prepare($sql);$s->execute($p);return $s->fetchAll(); }
function expense_record(int $id): ?array { $s=database()->prepare('SELECT e.*,s.name supplier_name,u.name AS created_by_name FROM expenses e LEFT JOIN suppliers s ON s.id=e.supplier_id LEFT JOIN users u ON u.id=e.created_by WHERE e.id=:id');$s->execute(['id'=>$id]);$row=$s->fetch();if(!$row)return null;$s=database()->prepare('SELECT * FROM expense_items WHERE expense_id=:id ORDER BY id');$s->execute(['id'=>$id]);$row['items']=$s->fetchAll();$s=database()->prepare('SELECT * FROM expense_external_parts WHERE expense_id=:id ORDER BY id LIMIT 1');$s->execute(['id'=>$id]);$row['external_part']=$s->fetch()?:null;return $row; }
function expense_summary(): array { $r=database()->query("SELECT COALESCE(SUM(total_amount),0) total,COALESCE(SUM(CASE WHEN expense_date>=DATE_FORMAT(CURRENT_DATE,'%Y-%m-01') THEN total_amount ELSE 0 END),0) month_total,COALESCE(SUM(CASE WHEN YEARWEEK(expense_date,1)=YEARWEEK(CURRENT_DATE,1) THEN total_amount ELSE 0 END),0) week_total,COALESCE(SUM(CASE WHEN status IN('pending','partial','due') THEN balance_amount ELSE 0 END),0) pending FROM expenses WHERE status<>'cancelled'")->fetch()?:[];return ['total'=>(float)$r['total'],'month'=>(float)$r['month_total'],'week'=>(float)$r['week_total'],'pending'=>(float)$r['pending']]; }
function expense_validate(array $i): array { $e=[];if($i['category']==='')$e[]='Select an expense category.';if(($i['expense_type']??'general')==='external_part'){if((int)$i['job_card_id']<=0)$e[]='Enter a valid Related Job Card number (for example, JC-2609-00008).';if((int)$i['supplier_id']<=0)$e[]='Supplier is required for an external part expense.';if(empty($i['external_parts']))$e[]='Add at least one external part.';foreach($i['external_parts'] as $n=>$part){if($part['name']==='')$e[]='External part '.($n+1).' name is required.';if((float)$part['quantity']<=0)$e[]='External part '.($n+1).' quantity must be greater than zero.';if((float)$part['buying_price']<0||(float)$part['selling_price']<0)$e[]='External part prices cannot be negative.';}}else{if(!$i['items'])$e[]='Add at least one expense item.';foreach($i['items'] as $n=>$item){if($item['name']==='')$e[]='Item '.($n+1).' name is required.';if((float)$item['quantity']<=0)$e[]='Item '.($n+1).' quantity must be greater than zero.';if((float)$item['unit_price']<0)$e[]='Item '.($n+1).' price cannot be negative.';}}if((float)$i['discount']<0||(float)$i['tax_rate']<0||(float)$i['paid_amount']<0)$e[]='Discount, tax and payment cannot be negative.';return $e; }
function expense_category_input(?array $source=null): array { $source??=$_POST;return ['name'=>trim((string)($source['category_name']??'')),'description'=>trim((string)($source['description']??'')),'status'=>($source['status']??'active')==='inactive'?'inactive':'active']; }

function handle_expense_request(string $section): void
{
    ensure_expense_tables();$id=max(0,(int)($_GET['id']??$_POST['expense_id']??0));$errors=[];
    if($section==='expenses-categories'){$categoryRows=expense_category_rows();$title='Expense Categories';$sectionForHeader=$section;require __DIR__.'/../includes/header.php';require __DIR__.'/../views/expense-categories.php';require __DIR__.'/../includes/footer.php';return;}
    if(in_array($section,['expenses-category-add','expenses-category-edit'],true)){$category=expense_category_input();$categoryId=max(0,(int)($_GET['id']??$_POST['category_id']??0));if($section==='expenses-category-edit'&&$_SERVER['REQUEST_METHOD']!=='POST'){$s=database()->prepare('SELECT * FROM expense_categories WHERE id=:id');$s->execute(['id'=>$categoryId]);$categoryRecord=$s->fetch();if(!$categoryRecord){http_response_code(404);exit('Expense category not found.');}$category=expense_category_input($categoryRecord);}if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();if($category['name']==='')$errors[]='Category name is required.';if(!$errors){try{if($section==='expenses-category-add'){$code='EXP-CAT-'.str_pad((string)((int)database()->query('SELECT COALESCE(MAX(id),0)+1 FROM expense_categories')->fetchColumn()),3,'0',STR_PAD_LEFT);$s=database()->prepare('INSERT INTO expense_categories(category_code,category_name,description,status,created_by) VALUES(:code,:name,:description,:status,:user)');$s->execute(['code'=>$code,'name'=>$category['name'],'description'=>$category['description']?:null,'status'=>$category['status'],'user'=>current_user()['id']??null]);}else{database()->prepare('UPDATE expense_categories SET category_name=:name,description=:description,status=:status WHERE id=:id')->execute(['name'=>$category['name'],'description'=>$category['description']?:null,'status'=>$category['status'],'id'=>$categoryId]);}flash('success','Expense category saved.');redirect($_POST['return_to']??'index.php?page=admin&section=expenses-categories');}catch(Throwable $e){$errors[]='Category name already exists or could not be saved.';}}}$title=$section==='expenses-category-edit'?'Edit Expense Category':'Add Expense Category';$sectionForHeader=$section;require __DIR__.'/../includes/header.php';require __DIR__.'/../views/expense-category-form.php';require __DIR__.'/../includes/footer.php';return;}
    if($section==='expenses-category-toggle'&&$_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$categoryId=max(0,(int)$_POST['category_id']);$s=database()->prepare("UPDATE expense_categories SET status=IF(status='active','inactive','active') WHERE id=:id");$s->execute(['id'=>$categoryId]);redirect('index.php?page=admin&section=expenses-categories');}
    if($section==='expenses-delete'&&$_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$record=expense_record($id);if(!$record){http_response_code(404);exit('Expense not found.');}if(($record['created_by']??null)!==null&&((current_user()['role']??'')==='cashier')&&(int)$record['created_by']!==(int)(current_user()['id']??0)){http_response_code(403);exit('You can only change expenses created by you.');}database()->prepare("UPDATE expenses SET status='cancelled' WHERE id=:id")->execute(['id'=>$id]);flash('success','Expense cancelled.');redirect('index.php?page=admin&section=expenses');}
    if(in_array($section,['expenses-view','expenses-edit'],true)){$record=expense_record($id);if(!$record){http_response_code(404);exit('Expense not found.');}if(($record['created_by']??null)!==null&&((current_user()['role']??'')==='cashier')&&(int)$record['created_by']!==(int)(current_user()['id']??0)){http_response_code(403);exit('You can only access expenses created by you.');}if($section==='expenses-view'){$title='View Expense';$sectionForHeader=$section;require __DIR__.'/../includes/header.php';require __DIR__.'/../views/expense-view.php';require __DIR__.'/../includes/footer.php';return;}}
    if ($section==='expenses-edit' && isset($record)) { $record['items']=array_map(static fn($item)=>['name'=>$item['item_name'],'quantity'=>$item['quantity'],'unit_price'=>$item['unit_price']],$record['items']); if($record['external_part']){foreach(['part_name'=>'external_part_name','part_code'=>'external_part_code','quantity'=>'external_quantity','unit_cost'=>'external_unit_cost','vendor_name'=>'vendor_supplier_name','invoice_no'=>'external_invoice_no','job_card_id'=>'job_card_id','vehicle_id'=>'vehicle_id'] as $from=>$to)$record[$to]=$record['external_part'][$from]??'';} }
    $input=expense_input_extended($section==='expenses-edit'?$record??null:null);if($section==='expenses-add'&&$_SERVER['REQUEST_METHOD']!=='POST'&&!$input['items'])$input['items']=[['name'=>'','quantity'=>'1','unit_price'=>'0']];
    if(in_array($section,['expenses-add','expenses-edit'],true)&&$_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$input=expense_input_extended();$errors=expense_validate($input);if(!$errors){$itemSubtotal=$input['expense_type']==='external_part'?(float)$input['external_quantity']*(float)$input['external_unit_cost']:0;if($input['expense_type']!=='external_part')foreach($input['items'] as $item)$itemSubtotal+=(float)$item['quantity']*(float)$item['unit_price'];$discount=min((float)$input['discount'],$itemSubtotal);$tax=max(0,($itemSubtotal-$discount)*(float)$input['tax_rate']/100);$total=$itemSubtotal-$discount+$tax;$paid=$input['payment_terms']==='cash'?$total:($input['payment_terms']==='credit'?0:min($total,(float)$input['paid_amount']));$status=$input['status'];if($status!=='draft'){if($input['payment_terms']==='cash'||$paid>=$total)$status='paid';elseif($paid>0)$status='partial';elseif($input['payment_terms']==='credit')$status='due';}$pdo=database();$pdo->beginTransaction();try{$values=['expense_date'=>$input['expense_date'],'category'=>$input['category'],'expense_type'=>$input['expense_type'],'reference_no'=>$input['reference_no']?:null,'description'=>$input['description'],'supplier_id'=>$input['supplier_id']?:null,'vendor_supplier_name'=>$input['vendor_supplier_name']?:null,'job_card_id'=>$input['job_card_id']?:null,'vehicle_id'=>$input['vehicle_id']?:null,'payment_terms'=>$input['payment_terms'],'payment_method'=>$input['payment_method'],'location'=>$input['location']?:null,'subtotal'=>$itemSubtotal,'discount'=>$discount,'tax_rate'=>(float)$input['tax_rate'],'tax_amount'=>$tax,'total_amount'=>$total,'paid_amount'=>$paid,'balance_amount'=>max(0,$total-$paid),'payment_date'=>$input['payment_date']?:null,'payment_note'=>$input['payment_note']?:null,'notes'=>$input['notes']?:null,'status'=>$status,'created_by'=>current_user()['id']??null];if($section==='expenses-add'){$s=$pdo->prepare('INSERT INTO expenses (expense_no,expense_date,category,expense_type,reference_no,description,supplier_id,vendor_supplier_name,job_card_id,vehicle_id,payment_terms,payment_method,location,subtotal,discount,tax_rate,tax_amount,total_amount,paid_amount,balance_amount,payment_date,payment_note,notes,status,created_by) VALUES (:expense_no,:expense_date,:category,:expense_type,:reference_no,:description,:supplier_id,:vendor_supplier_name,:job_card_id,:vehicle_id,:payment_terms,:payment_method,:location,:subtotal,:discount,:tax_rate,:tax_amount,:total_amount,:paid_amount,:balance_amount,:payment_date,:payment_note,:notes,:status,:created_by)');$s->execute(array_merge(['expense_no'=>'TMP-'.bin2hex(random_bytes(4))],$values));$saved=(int)$pdo->lastInsertId();$pdo->prepare('UPDATE expenses SET expense_no=:no WHERE id=:id')->execute(['no'=>'EXP-'.date('ymd').'-'.str_pad((string)$saved,4,'0',STR_PAD_LEFT),'id'=>$saved]);}else{$values['id']=$id;$pdo->prepare('UPDATE expenses SET expense_date=:expense_date,category=:category,expense_type=:expense_type,reference_no=:reference_no,description=:description,supplier_id=:supplier_id,vendor_supplier_name=:vendor_supplier_name,job_card_id=:job_card_id,vehicle_id=:vehicle_id,payment_terms=:payment_terms,payment_method=:payment_method,location=:location,subtotal=:subtotal,discount=:discount,tax_rate=:tax_rate,tax_amount=:tax_amount,total_amount=:total_amount,paid_amount=:paid_amount,balance_amount=:balance_amount,payment_date=:payment_date,payment_note=:payment_note,notes=:notes,status=:status WHERE id=:id')->execute(array_diff_key($values,['created_by'=>true]));$saved=$id;}$pdo->prepare('DELETE FROM expense_items WHERE expense_id=:id')->execute(['id'=>$saved]);$pdo->prepare('DELETE FROM expense_external_parts WHERE expense_id=:id')->execute(['id'=>$saved]);if($input['expense_type']==='external_part'){$s=$pdo->prepare('INSERT INTO expense_external_parts (expense_id,job_card_id,vehicle_id,part_name,part_code,quantity,unit_cost,total_cost,supplier_id,vendor_name,invoice_no) VALUES (:expense_id,:job_card_id,:vehicle_id,:part_name,:part_code,:quantity,:unit_cost,:total_cost,:supplier_id,:vendor_name,:invoice_no)');$s->execute(['expense_id'=>$saved,'job_card_id'=>$input['job_card_id']?:null,'vehicle_id'=>$input['vehicle_id']?:null,'part_name'=>$input['external_part_name'],'part_code'=>$input['external_part_code']?:null,'quantity'=>(float)$input['external_quantity'],'unit_cost'=>(float)$input['external_unit_cost'],'total_cost'=>(float)$input['external_quantity']*(float)$input['external_unit_cost'],'supplier_id'=>$input['supplier_id']?:null,'vendor_name'=>$input['vendor_supplier_name']?:null,'invoice_no'=>$input['external_invoice_no']?:null]);}else{$s=$pdo->prepare('INSERT INTO expense_items (expense_id,item_name,quantity,unit_price,amount) VALUES (:expense_id,:item_name,:quantity,:unit_price,:amount)');foreach($input['items'] as $item)$s->execute(['expense_id'=>$saved,'item_name'=>$item['name'],'quantity'=>(float)$item['quantity'],'unit_price'=>(float)$item['unit_price'],'amount'=>(float)$item['quantity']*(float)$item['unit_price']]);}$pdo->commit();flash('success','Expense saved successfully.');redirect('index.php?page=admin&section=expenses');}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$errors[]='Expense could not be saved.';}}}
    if(in_array($section,['expenses-add','expenses-edit'],true)){$suppliers=expense_suppliers();$categories=expense_categories();$title=$section==='expenses-edit'?'Edit Expense':'New Expense';$sectionForHeader=$section;require __DIR__.'/../includes/header.php';require __DIR__.'/../views/expense-form.php';require __DIR__.'/../includes/footer.php';return;}
    $filters=['search'=>trim((string)($_GET['search']??'')),'status'=>in_array($_GET['status']??'', ['pending','paid','partial','due','draft','cancelled'],true)?$_GET['status']:'','from'=>preg_match('/^\d{4}-\d{2}-\d{2}$/',$_GET['from']??'')?$_GET['from']:'','to'=>preg_match('/^\d{4}-\d{2}-\d{2}$/',$_GET['to']??'')?$_GET['to']:'','created_by'=>((current_user()['role']??'')==='cashier')?(int)(current_user()['id']??0):0];$rows=expense_rows($filters);$summary=expense_summary();$title='Expenses';$sectionForHeader=$section;require __DIR__.'/../includes/header.php';require __DIR__.'/../views/expenses.php';require __DIR__.'/../includes/footer.php';
}
